mapper.select:
select t.eps_id,t.eps_id epsId,t.event_hours,t.event_hours eventHours,t.event_id,t.event_id
eventId,t.staff_name,t.staff_name staffName,t.status_cd,t.status_cd
statusCd,t.state,t.event_result,t.event_result eventResult,t.community_id,t.community_id
communityId,t.event_reason,t.event_reason eventReason,t.staff_id,t.staff_id staffId,t.create_time createTime
from event_pool_staff t
left join event_pool ep on t.event_id = ep.event_id
left join event_rule er on ep.rule_id = er.rule_id
left join event_template et on er.template_id = et.template_id
where 1 =1 and ep.status_cd = '0' and er.status_cd = '0' and et.status_cd = '0'

    and t.eps_id= #{epsId}


    and t.event_hours= #{eventHours}


    and t.event_id= #{eventId}


    and t.staff_name= #{staffName}


    and t.status_cd= #{statusCd}


    and t.state= #{state}


    and t.event_result= #{eventResult}


    and t.community_id= #{communityId}


    and t.event_reason= #{eventReason}


    and t.staff_id= #{staffId}

order by t.create_time desc

    limit #{page}, #{row}

